    expect(callbackFn2).toHaveBeenCalledTimes(1);
    expect(callbackFn1).toHaveBeenCalledTimes(0);

    fireEvent.input(screen.getAllByRole('textbox')[1], {
      target: { name: 'sec', value: 'test' },
